def availability(spec):
    def a(node):
        if isinstance(node, (int, float)):
            return float(node)
        kind, parts = node[0], node[1:]
        if kind == "series":
            out = 1.0
            for p in parts:
                out *= a(p)
            return out
        down = 1.0
        for p in parts:
            down *= 1.0 - a(p)
        return 1.0 - down
    value = a(spec)
    return [value, (1.0 - value) * 365 * 24 * 60]

