class Autocomplete:
    def __init__(self, k):
        self.k = k
        self.root = {}                 # char -> child dict; "$" holds the count at a terminal

    def add(self, query, count):
        node = self.root
        for ch in query:
            node = node.setdefault(ch, {})
        node["$"] = node.get("$", 0) + count

    def _find(self, text):
        node = self.root
        for ch in text:
            node = node.get(ch)
            if node is None:
                return None
        return node

    def top(self, prefix):
        start = self._find(prefix)
        if start is None:
            return []
        found = []
        stack = [(start, prefix)]
        while stack:
            node, text = stack.pop()
            for ch, child in node.items():
                if ch == "$":
                    found.append((-child, text))
                else:
                    stack.append((child, text + ch))
        found.sort()
        return [text for _, text in found[:self.k]]

    def count(self, query):
        node = self._find(query)
        return node.get("$", 0) if node else 0

