class CircuitBreaker:
    def __init__(self, failure_threshold, reset_timeout, half_open_successes):
        self.threshold, self.timeout, self.needed = failure_threshold, reset_timeout, half_open_successes
        self.mode = "closed"
        self.failures = 0
        self.successes = 0
        self.opened_at = 0

    def state(self, now):
        if self.mode == "open" and now - self.opened_at >= self.timeout:
            self.mode = "half_open"
            self.successes = 0
        return self.mode

    def allow(self, now):
        return self.state(now) != "open"

    def _open(self, now):
        self.mode, self.opened_at = "open", now

    def record(self, success, now):
        mode = self.state(now)
        if mode == "open":
            return
        if mode == "closed":
            if success:
                self.failures = 0
            else:
                self.failures += 1
                if self.failures >= self.threshold:
                    self._open(now)
        else:                                   # half_open
            if success:
                self.successes += 1
                if self.successes >= self.needed:
                    self.mode, self.failures = "closed", 0
            else:
                self._open(now)

